import { NativeStackScreenProps } from '@react-navigation/native-stack';
import React, { useMemo, useRef, useState } from 'react';
import {
    Dimensions,
    FlatList,
    Image,
    ScrollView,
    StatusBar,
    Text,
    TouchableOpacity,
    View
} from 'react-native';
import { RootStackParamList } from '../../navigation/types';
import { styles } from './index.styles';

type Props = NativeStackScreenProps<RootStackParamList, 'HotelDetail'>;

const { width } = Dimensions.get('window');

const HotelDetailScreen = ({ route, navigation }: Props) => {
    const { hotelId, hotelName } = route.params;
    const [currentImageIndex, setCurrentImageIndex] = useState(0);

    // 模拟酒店图片数据
    const hotelImages = [
        'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80',
        'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=800&q=80',
        'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?auto=format&fit=crop&w=800&q=80',
        'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=800&q=80',
    ];

    // 模拟房型数据
    const roomTypes = [
        {
            id: '1',
            name: '经典双床房',
            price: 198,
            specs: '2张1.2米单人床 40㎡',
            img: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80'
        },
        {
            id: '2',
            name: '豪华大床房',
            price: 688,
            specs: '1张1.8米大床 45㎡',
            img: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80'
        },
        {
            id: '3',
            name: '行政套房',
            price: 2888,
            specs: '1张2.0米特大床 80㎡',
            img: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80'
        },
    ];

    // 逻辑：按价格从低到高排序
    const sortedRooms = useMemo(() => {
        return [...roomTypes].sort((a, b) => a.price - b.price);
    }, []);

    // 渲染轮播图
    const renderBannerItem = ({ item }: { item: string }) => (
        <Image source={{ uri: item }} style={styles.bannerImage} />
    );

    // 处理滚动事件
    const onViewableItemsChanged = useRef(({ viewableItems }: any) => {
        if (viewableItems.length > 0) {
            setCurrentImageIndex(viewableItems[0].index);
        }
    }).current;

    return (
        <View style={styles.container}>
            <StatusBar barStyle="light-content" translucent backgroundColor="transparent" />

            {/* 1. 顶部导航 (沉浸式) */}
            <View style={styles.headerOverlay}>
                {/* <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backBtn}>
                    <Text style={styles.backText}>‹</Text>
                </TouchableOpacity> */}
                <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
                    <Text style={styles.backIcon}>{'<'}</Text>
                </TouchableOpacity>

                <Text style={styles.headerTitle} numberOfLines={1}>{hotelName}</Text>
                <View style={styles.headerRight} />
            </View>

            <ScrollView bounces={false} showsVerticalScrollIndicator={false}>
                {/* 2. 大图 Banner (支持左右滚动) */}
                <View style={styles.bannerContainer}>
                    <FlatList
                        data={hotelImages}
                        renderItem={renderBannerItem}
                        keyExtractor={(_, index) => index.toString()}
                        horizontal
                        pagingEnabled
                        showsHorizontalScrollIndicator={false}
                        onViewableItemsChanged={onViewableItemsChanged}
                        viewabilityConfig={{ viewAreaCoveragePercentThreshold: 50 }}
                    />
                    {/* 图片指示器 */}
                    <View style={styles.indicatorContainer}>
                        {hotelImages.map((_, index) => (
                            <View
                                key={index}
                                style={[
                                    styles.indicator,
                                    index === currentImageIndex && styles.indicatorActive
                                ]}
                            />
                        ))}
                    </View>
                </View>

                {/* 3. 酒店基础信息卡片 */}
                <View style={styles.card}>
                    <View style={styles.hotelHeader}>
                        <Text style={styles.hotelName}>{hotelName}</Text>
                        <View style={styles.badge}>
                            <Text style={styles.badgeText}>口碑榜</Text>
                            <Text style={styles.badgeText}>上榜酒店</Text>
                        </View>
                    </View>

                    <View style={styles.starRow}>
                        <View style={styles.stars}>
                            {[1, 2, 3, 4, 5].map(i => (
                                <Text key={i} style={styles.starIcon}>★</Text>
                            ))}
                        </View>
                        <View style={styles.rankingTag}>
                            <Text style={styles.rankingText}>上海美景酒店榜 No.16</Text>
                            <Text style={styles.rankingArrow}>›</Text>
                        </View>
                    </View>

                    {/* 设施简述 */}
                    <View style={styles.facilityContainer}>
                        {[
                            { n: '2025年开业', i: '🏢' },
                            { n: '新中式风', i: '🏮' },
                            { n: '免费停车', i: '🅿️' },
                            { n: '设施政策', i: '➡️' },
                        ].map((item, idx) => (
                            <View key={idx} style={styles.facilityItem}>
                                <Text style={styles.facilityIcon}>{item.i}</Text>
                                <Text style={styles.facilityName}>{item.n}</Text>
                            </View>
                        ))}
                    </View>

                    {/* 评分和地址 */}
                    <View style={styles.infoRow}>
                        <View style={styles.ratingBox}>
                            <Text style={styles.ratingScore}>4.8</Text>
                            <Text style={styles.ratingLabel}>超棒</Text>
                            <Text style={styles.ratingCount}>4695条</Text>
                        </View>
                        <View style={styles.commentPreview}>
                            <Text style={styles.commentText}>"中式风格装修，舒适安逸"</Text>
                        </View>
                    </View>

                    {/* 地址 */}
                    <View style={styles.addressRow}>
                        <View style={styles.addressContent}>
                            <Text style={styles.distanceText}>距塘桥地铁站步行1.5公里,约22分钟</Text>
                            <Text style={styles.addressText}>浦东新区浦明路868弄3号楼</Text>
                        </View>
                        <View style={styles.mapBtn}>
                            <Text style={styles.mapIcon}>📍</Text>
                            <Text style={styles.mapText}>地图</Text>
                        </View>
                    </View>
                </View>

                {/* 4. 日历间夜选择 */}
                <View style={styles.calendarCard}>
                    <View style={styles.dateRow}>
                        <View style={styles.dateBox}>
                            <Text style={styles.dateLarge}>1月9日</Text>
                            <View style={styles.dateTag}>
                                <Text style={styles.dateTagText}>今天</Text>
                            </View>
                        </View>
                        <View style={styles.nightBadge}>
                            <Text style={styles.nightText}>1晚</Text>
                        </View>
                        <View style={styles.dateBox}>
                            <Text style={styles.dateLarge}>1月10日</Text>
                            <View style={styles.dateTag}>
                                <Text style={styles.dateTagText}>明天</Text>
                            </View>
                        </View>
                        <Text style={styles.arrowIcon}>›</Text>
                    </View>
                    <View style={styles.tipRow}>
                        <Text style={styles.tipText}>当前已过0点,如需今天凌晨6点前入住,请选择"今天凌晨"</Text>
                    </View>
                    {/* 筛选标签 */}
                    <View style={styles.filterRow}>
                        {['含早餐', '大床房', '双床房', '免费取消'].map((tag, idx) => (
                            <View key={idx} style={styles.filterTag}>
                                <Text style={styles.filterTagText}>{tag}</Text>
                                {tag === '筛选' && <Text style={styles.filterIcon}>🔽</Text>}
                            </View>
                        ))}
                    </View>
                </View>

                {/* 5. 房型价格列表 */}
                <View style={styles.roomListContainer}>
                    {sortedRooms.map((room) => (
                        <TouchableOpacity key={room.id} style={styles.roomItem}>
                            <Image source={{ uri: room.img }} style={styles.roomImage} />
                            <View style={styles.roomInfo}>
                                <View style={styles.roomDetail}>
                                    <Text style={styles.roomName}>{room.name}</Text>
                                    <Text style={styles.roomSpecs}>{room.specs}</Text>
                                </View>
                                <View style={styles.roomPriceRow}>
                                    <View style={styles.priceBox}>
                                        <Text style={styles.priceSymbol}>¥</Text>
                                        <Text style={styles.priceText}>{room.price}</Text>
                                    </View>
                                    <TouchableOpacity style={styles.bookBtn}>
                                        <Text style={styles.bookBtnText}>查看房型</Text>
                                    </TouchableOpacity>
                                </View>
                            </View>
                        </TouchableOpacity>
                    ))}
                </View>

                <View style={{ height: 50 }} />
            </ScrollView>
        </View>
    );
};

export default HotelDetailScreen;
